CREATE TABLE public.experience_editors (user_id uuid PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.experience_editors TO authenticated;
GRANT ALL ON public.experience_editors TO service_role;
ALTER TABLE public.experience_editors ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own editor permission" ON public.experience_editors FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.experience_access_requests (user_id uuid PRIMARY KEY DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.experience_access_requests TO authenticated;
GRANT ALL ON public.experience_access_requests TO service_role;
ALTER TABLE public.experience_access_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Request own access" ON public.experience_access_requests FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid());
CREATE POLICY "Read own request" ON public.experience_access_requests FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.is_experience_editor() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.experience_editors WHERE user_id = auth.uid()); $$;
REVOKE ALL ON FUNCTION public.is_experience_editor() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_experience_editor() TO anon, authenticated, service_role;
CREATE TABLE public.experience_content (slug text PRIMARY KEY, content jsonb NOT NULL, active boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.experience_content TO anon;
GRANT SELECT, UPDATE ON public.experience_content TO authenticated;
GRANT ALL ON public.experience_content TO service_role;
ALTER TABLE public.experience_content ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read active experience" ON public.experience_content FOR SELECT TO anon, authenticated USING (active OR public.is_experience_editor());
CREATE POLICY "Editors update experience" ON public.experience_content FOR UPDATE TO authenticated USING (public.is_experience_editor()) WITH CHECK (public.is_experience_editor());
CREATE TABLE public.experience_offers (id text PRIMARY KEY, experience_slug text NOT NULL REFERENCES public.experience_content(slug), content jsonb NOT NULL, active boolean NOT NULL DEFAULT true, validated boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.experience_offers TO anon;
GRANT SELECT, UPDATE ON public.experience_offers TO authenticated;
GRANT ALL ON public.experience_offers TO service_role;
ALTER TABLE public.experience_offers ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read validated offers or editor drafts" ON public.experience_offers FOR SELECT TO anon, authenticated USING ((active AND validated AND EXISTS (SELECT 1 FROM public.experience_content WHERE slug = experience_slug AND active)) OR public.is_experience_editor());
CREATE POLICY "Editors update offers" ON public.experience_offers FOR UPDATE TO authenticated USING (public.is_experience_editor()) WITH CHECK (public.is_experience_editor());